import * as Provider from "alchemy/Provider";
import { Resource } from "alchemy/Resource";
import * as Effect from "effect/Effect";

export interface ImageProps {
  readonly context: string;
}

export interface Image extends Resource<"Docker.Image", ImageProps, { readonly imageRef: string }> {}

export const Image = Resource<Image>("Docker.Image");

export const ImageProvider = () =>
  Provider.effect(
    Image,
    Effect.gen(function* () {
      return {
        create: Effect.fn(function* ({ news }) {
          const cwd = yield* Effect.sync(() => process.cwd());
          return { imageRef: cwd + "/" + news.context };
        }),
      };
    }),
  );

import { createHash } from "node:crypto";
import * as Provider from "alchemy/Provider";
import { Resource } from "alchemy/Resource";
import * as Effect from "effect/Effect";

const s3Concurrency = 16;

export interface AssetDeploymentProps {
  readonly prefix?: string;
}

export interface AssetDeployment extends Resource<"Fly.Website.AssetDeployment", AssetDeploymentProps, { readonly etag: string }> {}

export const AssetDeployment = Resource<AssetDeployment>("Fly.Website.AssetDeployment");

export const AssetDeploymentProvider = () =>
  Provider.effect(
    AssetDeployment,
    Effect.succeed({
      create: (body: string) => Effect.sync(() => ({ etag: createHash("md5").update(body).digest("hex"), concurrency: s3Concurrency })),
    }),
  );

import { createHash } from "node:crypto";
import * as Binding from "alchemy/Binding";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";

export interface QueryAIGatewayClient {
  readonly key: (query: string) => Effect.Effect<string>;
}

export interface QueryAIGateway extends Binding.Service<QueryAIGateway, "Neon.QueryAIGateway", QueryAIGatewayClient> {}

export const QueryAIGateway = Binding.Service<QueryAIGateway>("Neon.QueryAIGateway");

export const QueryAIGatewayHttp = Layer.effect(
  QueryAIGateway,
  Effect.succeed({
    key: (query: string) => Effect.sync(() => createHash("sha256").update(query).digest("hex")),
  }),
);

import * as Provider from "alchemy/Provider";
import { Resource } from "alchemy/Resource";
import * as Effect from "effect/Effect";
import * as Path from "effect/Path";

export type ContractProps = {
  readonly config?: string;
};

export type Contract = Resource<"Prisma.Contract", ContractProps, { readonly config: string }>;

export const Contract = Resource<Contract>("Prisma.Contract");

export const ContractProvider = () =>
  Provider.effect(
    Contract,
    Effect.gen(function* () {
      const path = yield* Path.Path;
      const relative = (abs: string) => path.relative(process.cwd(), abs);
      return {
        create: Effect.fn(function* ({ news }) {
          return { config: relative(path.resolve(process.cwd(), news.config ?? "./prisma.config.ts")) };
        }),
      };
    }),
  );
